  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Attempts to move a player from one position to another, handling box pushing and updating state.
   * Algorithm:
   *   1. Get entity at from position - must be a Player
   *   2. Get entity at to position:
   *      a. If to position is Empty or null:
   *         - Move player from 'from' to 'to'
   *         - Add transition: currentTransition.add(from, to)
   *         - Return Success
   *      b. If to position is a Box:
   *         - Check if box.playerId matches the moving player's id
   *         - If not matching, return Failed with "Cannot push another player's box"
   *         - Compute pushPosition = to + (to - from) direction
   *         - Get entity at pushPosition:
   *           - If pushPosition is Empty or null:
   *             - Move box from 'to' to pushPosition
   *             - Move player from 'from' to 'to'
   *             - Add transitions: currentTransition.add(from, to), currentTransition.add(to, pushPosition)
   *             - Call checkpoint()
   *             - Return Success
   *           - Else return Failed with "Cannot push box - blocked"
   *      c. If to position is Wall, Player, or unpushable box:
   *         - Return Failed with appropriate reason (e.g., "Blocked by wall", "Blocked by player")
   * Related Features: entities, currentTransition
   * Related Classes: Position, Player, Box, Empty, Wall, Entity, ActionResult, Success, Failed, GameStateTransition
   * Input: from : Position - current position of the player; to : Position - desired new position
   * Output: ActionResult - Success if move was valid, Failed with reason otherwise
   * Pre-condition: from position contains a Player entity; to position is within board boundaries
   * Post-condition: If successful, player (and possibly box) positions are updated, transition is recorded, checkpoint may be created
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void move(final Position from, final Position to)
  {
    // Get entity at from position - must be a Player
    Entity fromEntity = getEntity(from);
    if (!(fromEntity instanceof Player)) {
      // Not a player at from position, nothing to do
      return;
    }
    Player player = (Player) fromEntity;
    
    // Get entity at to position
    Entity toEntity = getEntity(to);
    
    // Case a: to position is Empty or null
    if (toEntity == null || toEntity instanceof Empty) {
      // Move player from 'from' to 'to'
      getEntities().remove(from);
      getEntities().put(to, player);
      // Add transition
      if (getCurrentTransition() != null) {
        getCurrentTransition().add(from, to);
      }
      return;
    }
    
    // Case b: to position is a Box
    if (toEntity instanceof Box) {
      Box box = (Box) toEntity;
      // Check if box.playerId matches the moving player's id
      if (box.getPlayerId() != player.getId()) {
        // Cannot push another player's box
        return;
      }
      // Compute pushPosition = to + (to - from) direction
      int dx = to.getX() - from.getX();
      int dy = to.getY() - from.getY();
      Position pushPosition = Pa22Factory.eINSTANCE.createPosition();
      pushPosition.setX(to.getX() + dx);
      pushPosition.setY(to.getY() + dy);
      
      // Get entity at pushPosition
      Entity pushEntity = getEntity(pushPosition);
      
      // If pushPosition is Empty or null
      if (pushEntity == null || pushEntity instanceof Empty) {
        // Move box from 'to' to pushPosition
        getEntities().remove(to);
        getEntities().put(pushPosition, box);
        // Move player from 'from' to 'to'
        getEntities().remove(from);
        getEntities().put(to, player);
        // Add transitions
        if (getCurrentTransition() != null) {
          getCurrentTransition().add(from, to);
          getCurrentTransition().add(to, pushPosition);
        }
        // Call checkpoint()
        checkpoint();
        return;
      } else {
        // Cannot push box - blocked
        return;
      }
    }
    
    // Case c: to position is Wall, Player, or unpushable box
    // Nothing to do - blocked
    return;
  }

